// OpenAI provider for anymodel
// Translates between Anthropic Messages API and OpenAI Chat Completions API
// Works with any OpenAI-compatible endpoint (OpenAI, Azure, Together, Groq, vLLM, LMStudio, etc.)

// ── Request translation (Anthropic → OpenAI) ────────────

export const INTERNAL_EFFORT_FIELD = '__anymodel_effort';

export function normalizeReasoningEffort(effort) {
  if (typeof effort !== 'string') return null;
  const normalized = effort.toLowerCase();
  if (['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max'].includes(normalized)) return normalized;
  return null;
}

function isNativeReasoningModel(model) {
  const m = String(model || '').toLowerCase();
  return /(^|[/_-])(gpt-[56]|o[1-9]\d*)(?=$|[-_./])/.test(m);
}
